    public void testRandom_CountAndStartEnd_ReturnsExpectedResult() {
        String result = randomStringUtils.random(COUNT, START, END);
        assertThat(result.length(), is(COUNT));
        for (int i = 0; i < COUNT; i++) {
            int charCode = result.charAt(i);
            if (LETTERS) {
                Assert.assertTrue('a' <= charCode && charCode <= 'z');
            } else if (NUMBERS) {
                Assert.assertTrue('0' <= charCode && charCode <= '9');
            } else {
                Assert.assertTrue(START <= charCode && charCode <= END);
            }
        }
