    private CharSequenceTranslator translator;
    private StringWriter writer;

    @Before
    public void setUp() {
        translator = new CharSequenceTranslator();
        writer = new StringWriter(10);
    }

    @Test
    public void testNullInput() {
        Assert.assertNull(translator.translate((CharSequence) null));
    }

    @Test
    public void testEmptyInput() {
        translator.translate("", writer);
        Assert.assertEquals("", writer.toString());
    }

    @Test
    public void testTranslateWithOneCharacter() {
        translator.with(new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index) {
                return 'A';
            }
        }).translate("a", writer);
        Assert.assertEquals("A", writer.toString());
    }

    @Test
    public void testTranslateWithMultipleCharacters() {
        translator.with(new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index) {
                if (index == 0) {
                    return 'A';
                } else if (index == 1) {
                    return 'B';
                }
                return -1;
            }
        }).translate("ab", writer);
        Assert.assertEquals("AB", writer.toString());
    }

    @Test(expected = RuntimeException.class)
    public void testIOException() throws IOException {
        Writer out = mock(Writer.class);
        translator.translate("abc", out);
        verify(out).write("abc");
        // simulate an IOException
        doThrow(new IOException()).when(out).write("def");
        translator.translate("def", out);
    }

    @Test
    public void testHex() {
        Assert.assertEquals("41", CharSequenceTranslator.hex('A'));
    }
}
