    @Test
    public void testStop_whenNotRunning_throwsIllegalStateException() {
        stopWatch.runningState = STATE_STOPPED;
        Assert.assertThat( () -> stopWatch.stop(), throwsException(IllegalStateException.class));
    }

    @Test
    public void testStop_whenRunning_stopsAndSetsStateToStopped() {
        stopWatch.start();
        stopWatch.stop();
        Assert.assertEquals(STATE_STOPPED, stopWatch.runningState);
    }

    @Test
    public void testGetTime_whenNotStarted_returnsZero() {
        Assert.assertEquals(0L, stopWatch.getTime());
    }

    @Test
    public void testGetTime_whenRunning_returnsElapsedTimeSinceStart() {
        long startTime = System.currentTimeMillis();
        stopWatch.start();
        Thread.sleep(1000);
        long elapsedTime = stopWatch.getTime() - startTime;
        Assert.assertTrue(elapsedTime > 950 && elapsedTime < 1050);
    }

    @Test
    public void testGetSplitTime_whenNotSplit_returnsZero() {
        Assert.assertEquals(0L, stopWatch.getSplitTime());
    }

    @Test
    public void testGetSplitTime_whenSplit_returnsElapsedTimeSinceLastSplit() {
        long startTime = System.currentTimeMillis();
        stopWatch.start();
        Thread.sleep(1000);
        stopWatch.split();
        Thread.sleep(2000);
        long elapsedTime = stopWatch.getSplitTime() - (System.currentTimeMillis() - startTime);
        Assert.assertTrue(elapsedTime > 1950 && elapsedTime < 2050);
    }
}
